// browser check = friendly UX; server check = real security
function validateAge(age) {
  return Number.isInteger(age) && age >= 0 && age <= 130;
}

// least privilege: check the role before the power
function deleteUser(requester, targetId) {
  if (requester.role !== "admin") return "Denied";
  return "Deleted " + targetId;
}

